def dedupe_reports(apps, schema_editor):
    """Earlier versions allowed repeat reports; keep the oldest per reporter and target."""
    Report = apps.get_model('community', 'Report')
    for field in ('post', 'comment'):
        seen = set()
        for report in Report.objects.filter(**{f'{field}__isnull': False}).order_by('created_at', 'pk'):
            key = (report.reporter_id, getattr(report, f'{field}_id'))
            if key in seen:
                report.delete()
            seen.add(key)


